import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"15、【謙】 艮下坤上","description":"溫公易說 - 15、【謙】 艮下坤上","frontmatter":{"title":"15、【謙】 艮下坤上","description":"溫公易說 - 15、【謙】 艮下坤上"},"headers":[],"relativePath":"classics/wengong/016.md","filePath":"classics/wengong/016.md"}'),l={name:"classics/wengong/016.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_15、【謙】-艮下坤上" tabindex="-1">15、【謙】 艮下坤上 <a class="header-anchor" href="#_15、【謙】-艮下坤上" aria-label="Permalink to “15、【謙】 艮下坤上”">​</a></h1><h3 id="彖曰-謙-亨。天道下濟而光明-地道卑而上行。天道虧盈而益謙-地道變盈而流謙。鬼神害盈而福謙-人道惡盈而好謙。謙尊而光-卑而不可逾。君子之終也。" tabindex="-1">彖曰：謙，亨。天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙。鬼神害盈而福謙，人道惡盈而好謙。謙尊而光，卑而不可逾。君子之終也。 <a class="header-anchor" href="#彖曰-謙-亨。天道下濟而光明-地道卑而上行。天道虧盈而益謙-地道變盈而流謙。鬼神害盈而福謙-人道惡盈而好謙。謙尊而光-卑而不可逾。君子之終也。" aria-label="Permalink to “彖曰：謙，亨。天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙。鬼神害盈而福謙，人道惡盈而好謙。謙尊而光，卑而不可逾。君子之終也。”">​</a></h3><p>人之將有行也，將有為也。施之以謙，則無不通也。君子之德，誠盛矣，業誠大矣。不謙以持之，則無以保其終也。故夫謙者，君子之終也。</p><h3 id="象曰-地中有山-謙。君子以裒多益寡-稱物平施。" tabindex="-1">象曰：地中有山，謙。君子以裒多益寡，稱物平施。 <a class="header-anchor" href="#象曰-地中有山-謙。君子以裒多益寡-稱物平施。" aria-label="Permalink to “象曰：地中有山，謙。君子以裒多益寡，稱物平施。”">​</a></h3><h3 id="初六-謙謙-君子用涉大川-吉-象曰-謙謙君子-卑以自牧也。" tabindex="-1">初六：謙謙，君子用涉大川，吉 象曰：謙謙君子，卑以自牧也。 <a class="header-anchor" href="#初六-謙謙-君子用涉大川-吉-象曰-謙謙君子-卑以自牧也。" aria-label="Permalink to “初六：謙謙，君子用涉大川，吉 象曰：謙謙君子，卑以自牧也。”">​</a></h3><h3 id="六二-鳴謙-貞吉-象曰-鳴謙貞吉-中心得也。" tabindex="-1">六二：鳴謙，貞吉 象曰：鳴謙貞吉，中心得也。 <a class="header-anchor" href="#六二-鳴謙-貞吉-象曰-鳴謙貞吉-中心得也。" aria-label="Permalink to “六二：鳴謙，貞吉 象曰：鳴謙貞吉，中心得也。”">​</a></h3><h3 id="九三-勞謙-君子有終-吉-象曰-勞謙君子-萬民服也。" tabindex="-1">九三：勞謙，君子有終，吉 象曰：勞謙君子，萬民服也。 <a class="header-anchor" href="#九三-勞謙-君子有終-吉-象曰-勞謙君子-萬民服也。" aria-label="Permalink to “九三：勞謙，君子有終，吉 象曰：勞謙君子，萬民服也。”">​</a></h3><p>勞謙，有勞而謙者也。</p><h3 id="六四-無不利-撝謙-象曰-無不利撝謙-不違則也。" tabindex="-1">六四：無不利，撝謙 象曰：無不利撝謙，不違則也。 <a class="header-anchor" href="#六四-無不利-撝謙-象曰-無不利撝謙-不違則也。" aria-label="Permalink to “六四：無不利，撝謙 象曰：無不利撝謙，不違則也。”">​</a></h3><h3 id="六五-不富以其鄰-利用侵伐-無不利-象曰-利用侵伐-徵不服也。" tabindex="-1">六五：不富以其鄰，利用侵伐，無不利 象曰：利用侵伐，徵不服也。 <a class="header-anchor" href="#六五-不富以其鄰-利用侵伐-無不利-象曰-利用侵伐-徵不服也。" aria-label="Permalink to “六五：不富以其鄰，利用侵伐，無不利 象曰：利用侵伐，徵不服也。”">​</a></h3><h3 id="上六-鳴謙-利用行師-徵邑國-象曰-鳴謙-志未得也。可用行師-徵邑國也。" tabindex="-1">上六：鳴謙，利用行師，徵邑國 象曰：鳴謙，志未得也。可用行師，徵邑國也。 <a class="header-anchor" href="#上六-鳴謙-利用行師-徵邑國-象曰-鳴謙-志未得也。可用行師-徵邑國也。" aria-label="Permalink to “上六：鳴謙，利用行師，徵邑國 象曰：鳴謙，志未得也。可用行師，徵邑國也。”">​</a></h3>',11)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
